import { setTimeout as sleep } from 'node:timers/promises'

import { HttpError, IngestConfigError, paginate, rawRows, type ErrorClassifier, type FetchContext } from '@chkit/plugin-ingest'

import { slackConfig, type SlackReaderConfig } from './config.js'

export type SlackEntity = Record<string, unknown>

export interface SlackClientDeps {
  config: SlackReaderConfig
  fetch: (url: string, init: RequestInit) => Promise<Response>
  token: () => string | undefined
  wait: (milliseconds: number, signal: AbortSignal) => Promise<void>
}

export interface CollectionRequest {
  method: 'conversations.list' | 'users.list' | 'conversations.history' | 'conversations.replies'
  field: 'channels' | 'members' | 'messages'
  idField: 'id' | 'ts'
  query?: Record<string, string>
  pageSize?: number
  /** Message endpoints support timestamp pagination without an opaque cursor. */
  timePagination?: boolean
}

export interface SlackPage { items: SlackEntity[]; cursor: string; hasMore: boolean }
export class SlackCursorExpiredError extends IngestConfigError {}

export const defaultSlackClientDeps: SlackClientDeps = {
  config: slackConfig,
  fetch: (url, init) => fetch(url, init),
  token: () => process.env.SLACK_API_TOKEN,
  wait: async (milliseconds, signal) => { await sleep(milliseconds, undefined, { signal }) },
}

/** Each page is validated inside attempt, so executor retry/cancellation owns every request. */
export function readCollection(
  context: FetchContext,
  request: CollectionRequest,
  deps: SlackClientDeps = defaultSlackClientDeps,
) {
  return paginate({
    context, label: `GET /api/${request.method}`,
    fetchPage: async (cursor: string | undefined, signal) => {
      const page = await fetchCollectionPage(request, cursor ?? '', signal, deps)
      // Empty/short pages can still have a cursor. Only cursor exhaustion ends a read.
      return { items: page.items, next: page.cursor || undefined }
    },
  })
}

/** Retains empty pages and continuation metadata needed by checkpointed readers. */
export async function readCollectionPage(context: FetchContext, request: CollectionRequest, cursor = '', deps: SlackClientDeps = defaultSlackClientDeps): Promise<SlackPage> {
  return context.attempt((signal) => fetchCollectionPage(request, cursor, signal, deps), { label: `GET /api/${request.method}` })
}

/** Discover independently in each reader; pipeline stream order is not a dependency. */
export async function discoverChannels(context: FetchContext, deps: SlackClientDeps = defaultSlackClientDeps): Promise<SlackEntity[]> {
  const channels: SlackEntity[] = []
  for await (const page of readChannelPages(context, deps)) channels.push(...page)
  return channels
}

/** Yield selected metadata pages directly; configured IDs must all be accessible. */
export async function* readChannelPages(context: FetchContext, deps: SlackClientDeps = defaultSlackClientDeps) {
  const config = deps.config
  const allowedTypes = ['public_channel', 'private_channel', 'im', 'mpim']
  if (config.conversationTypes.length === 0 || !config.conversationTypes.every((type) => allowedTypes.includes(type))) {
    throw new IngestConfigError('Slack conversationTypes must select public_channel, private_channel, im, or mpim.')
  }
  const selected = config.channels
  const missing = new Set(selected)
  for await (const page of readCollection(context, {
    method: 'conversations.list', field: 'channels', idField: 'id',
    query: { types: config.conversationTypes.join(','), exclude_archived: 'false' },
  }, deps)) {
    const channels = selected === undefined ? page : page.filter((channel) => selected.includes(entityId(channel, 'id')))
    for (const channel of channels) missing.delete(entityId(channel, 'id'))
    if (channels.length > 0) yield channels
  }
  for (const id of missing) {
    throw new IngestConfigError(`Configured Slack channel "${id}" was not found or is not accessible for conversationTypes.`)
  }
}

/** Scope row identities to the authenticated workspace, never its mutable display name. */
export async function getWorkspace(context: FetchContext, deps: SlackClientDeps = defaultSlackClientDeps): Promise<string> {
  return context.attempt(async (signal) => {
    const payload = await requestSlack('auth.test', {}, signal, deps)
    return entityId(payload, 'team_id')
  }, { label: 'POST /api/auth.test' })
}

/** Original fields stay under data; provider fields cannot overwrite envelope metadata. */
export function toSlackRows(
  items: readonly SlackEntity[],
  resource: string,
  teamId: string,
  idField: 'id' | 'ts',
  channelId?: string,
  sourceId = slackConfig.sourceId,
) {
  return rawRows(
    items.map((data) => ({
      source_id: sourceId, team_id: teamId,
      ...(channelId === undefined ? {} : { channel_id: channelId }), data,
    })),
    ({ data }) => JSON.stringify([
      sourceId, resource, teamId, ...(channelId === undefined ? [] : [channelId]), entityId(data, idField),
    ]),
  )
}

export function entityId(entity: SlackEntity, field: string): string {
  const value = entity[field]
  if (typeof value !== 'string' || value.trim().length === 0) {
    throw new IngestConfigError(`Slack entity is missing a valid ${field} string.`)
  }
  if (field === 'ts' && !/^\d+\.\d+$/.test(value)) {
    throw new IngestConfigError('Slack message ts must be an unmodified decimal timestamp string.')
  }
  return value
}

export const classifySlackError: ErrorClassifier = (cause) => {
  if (cause instanceof IngestConfigError || cause instanceof SyntaxError) return { kind: 'permanent' }
  // HTTP errors preserve Retry-After, server retries, and permanent 4xx semantics.
  return undefined
}

async function fetchCollectionPage(request: CollectionRequest, cursor: string, signal: AbortSignal, deps: SlackClientDeps): Promise<SlackPage> {
  const limit = request.pageSize ?? (request.field === 'messages' ? deps.config.messagePageSize : deps.config.pageSize)
  if (!Number.isSafeInteger(limit) || limit <= 0 || limit >= 1_000) throw new IngestConfigError('Slack page sizes must be safe integers between 1 and 999.')
  const query = { ...request.query, limit: String(limit), ...(cursor ? { cursor } : {}) }
  return parsePage(await requestSlack(request.method, query, signal, deps), request)
}

async function requestSlack(
  method: CollectionRequest['method'] | 'auth.test',
  query: Record<string, string>,
  signal: AbortSignal,
  deps: SlackClientDeps,
): Promise<Record<string, unknown>> {
  const token = deps.token()?.trim()
  if (!token) throw new IngestConfigError('Set SLACK_API_TOKEN before running Slack ingestion. Schema imports do not need credentials.')
  const interval = method === 'conversations.history' || method === 'conversations.replies'
    ? deps.config.messageIntervalMs : deps.config.requestIntervalMs
  if (!Number.isSafeInteger(interval) || interval < 0 || interval > 2_147_483_647) {
    throw new IngestConfigError('Slack request intervals must be non-negative safe integers within the timer range.')
  }
  await deps.wait(interval, signal)
  signal.throwIfAborted()
  const url = new URL(`https://slack.com/api/${method}`)
  for (const [key, value] of Object.entries(query)) url.searchParams.set(key, value)
  const response = await deps.fetch(url.toString(), {
    method: method === 'auth.test' ? 'POST' : 'GET',
    headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' },
    signal: AbortSignal.any([signal, AbortSignal.timeout(30_000)]),
    redirect: 'error',
  })
  if (!response.ok) throw await HttpError.fromResponse(response)
  const payload: unknown = await response.json()
  if (!isObject(payload) || typeof payload.ok !== 'boolean') {
    throw new IngestConfigError(`Slack ${method} returned an invalid response envelope.`)
  }
  // Slack reports authentication, permission, and transient errors in HTTP 200 responses.
  if (!payload.ok) {
    const code = typeof payload.error === 'string' ? payload.error : 'unknown_error'
    if (code === 'invalid_cursor') throw new SlackCursorExpiredError(`Slack ${method} pagination cursor expired.`)
    if (code === 'ratelimited' || code === 'rate_limited') {
      const headers = new Headers(response.headers)
      if (!headers.has('Retry-After')) headers.set('Retry-After', '60')
      throw await HttpError.fromResponse(new Response(JSON.stringify({ error: code }), { status: 429, headers }))
    }
    if (['internal_error', 'fatal_error', 'service_unavailable', 'request_timeout'].includes(code)) {
      throw await HttpError.fromResponse(new Response(JSON.stringify({ error: code }), { status: 503 }))
    }
    const needed = typeof payload.needed === 'string' ? ` Required scopes: ${payload.needed}.` : ''
    const repliesHint = method === 'conversations.replies' ? ' Disable includeReplies explicitly for history-only reads.' : ''
    throw new IngestConfigError(`Slack ${method} failed (${code}).${needed} Check SLACK_API_TOKEN, resource scopes, and conversation access.${repliesHint}`)
  }
  return payload
}

function parsePage(payload: Record<string, unknown>, request: CollectionRequest) {
  const values = payload[request.field]
  if (!Array.isArray(values)) throw new IngestConfigError(`Slack ${request.method} returned no ${request.field} array.`)
  const items = values.map((value: unknown) => {
    if (!isObject(value)) throw new IngestConfigError(`Slack ${request.method} returned an invalid entity.`)
    entityId(value, request.idField)
    if (request.field === 'messages' && value.reply_count !== undefined
      && (typeof value.reply_count !== 'number' || !Number.isSafeInteger(value.reply_count) || value.reply_count < 0)) {
      throw new IngestConfigError(`Slack ${request.method} returned an invalid reply_count.`)
    }
    return value
  })
  const metadata = payload.response_metadata
  if (metadata !== undefined && !isObject(metadata)) {
    throw new IngestConfigError(`Slack ${request.method} returned invalid response_metadata.`)
  }
  const next = isObject(metadata) ? metadata.next_cursor : undefined
  if (next !== undefined && next !== null && typeof next !== 'string') {
    throw new IngestConfigError(`Slack ${request.method} returned an invalid next_cursor.`)
  }
  const cursor = typeof next === 'string' ? next.trim() : ''
  if (payload.has_more !== undefined && typeof payload.has_more !== 'boolean') {
    throw new IngestConfigError(`Slack ${request.method} returned an invalid has_more flag.`)
  }
  if (payload.has_more === true && !cursor && !request.timePagination) {
    throw new IngestConfigError(`Slack ${request.method} reports more data without a pagination cursor; refusing an incomplete scan.`)
  }
  return { items, cursor, hasMore: payload.has_more === true || cursor.length > 0 }
}

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

import { definePipeline, defineStream } from '@chkit/plugin-ingest'

import { classifySlackError, defaultSlackClientDeps, type SlackClientDeps } from './client.js'
import { slackConfig, type SlackReaderConfig } from './config.js'
import { readChannels, slackChannelsRaw } from './sources/channels.js'
import { readUsers, slackUsersRaw } from './sources/users.js'
import { readMessages, slackMessagesRaw } from './sources/messages.js'
import { createSlackMessageStrategy } from './state.js'

const streamOptions = { classifyError: classifySlackError, batchSize: 500 }

// One installation pipeline, with independent streams for the three resource types.
// Destination names come from config.ts when the raw schemas load.
export function createSlackPipeline(config: SlackReaderConfig = slackConfig, deps: SlackClientDeps = defaultSlackClientDeps) {
  const boundConfig = { ...config, channels: config.channels ? [...config.channels] : undefined, conversationTypes: [...config.conversationTypes] }
  const client = { ...deps, config: boundConfig }
  return definePipeline({
    id: boundConfig.sourceId,
    tags: ['provider:slack'],
    maxStreams: 1,
    maxFetches: 1,
    maxLoads: 1,
    retry: { retries: 5, minTimeout: 1_000, maxTimeout: 60_000, randomize: true },
    streams: [
      defineStream({ ...streamOptions, id: `${boundConfig.sourceId}.channels`, tags: ['resource:channels'], destination: slackChannelsRaw, read: (context) => readChannels(context, client) }),
      defineStream({ ...streamOptions, id: `${boundConfig.sourceId}.users`, tags: ['resource:users'], destination: slackUsersRaw, read: (context) => readUsers(context, client) }),
      defineStream({ ...streamOptions, batchSize: 1, id: `${boundConfig.sourceId}.messages`, tags: ['resource:messages'], destination: slackMessagesRaw, incremental: createSlackMessageStrategy(boundConfig), read: (context) => readMessages(context, client) }),
    ],
  })
}

export const slack = createSlackPipeline()

import { rawTable, type FetchContext } from '@chkit/plugin-ingest'

import { defaultSlackClientDeps, getWorkspace, readChannelPages, toSlackRows, type SlackClientDeps } from '../client.js'
import { slackConfig } from '../config.js'

export const slackChannelsRaw = rawTable({ database: slackConfig.database, name: `${slackConfig.tablePrefix}_channels_raw` })

export async function* readChannels(context: FetchContext, deps: SlackClientDeps = defaultSlackClientDeps) {
  const teamId = await getWorkspace(context, deps)
  for await (const page of readChannelPages(context, deps)) {
    yield { rows: toSlackRows(page, 'channels', teamId, 'id', undefined, deps.config.sourceId) }
  }
}

import { rawTable, type FetchContext } from '@chkit/plugin-ingest'

import { defaultSlackClientDeps, getWorkspace, readCollection, toSlackRows, type SlackClientDeps } from '../client.js'
import { slackConfig } from '../config.js'

export const slackUsersRaw = rawTable({ database: slackConfig.database, name: `${slackConfig.tablePrefix}_users_raw` })

export async function* readUsers(context: FetchContext, deps: SlackClientDeps = defaultSlackClientDeps) {
  const teamId = await getWorkspace(context, deps)
  for await (const page of readCollection(context, { method: 'users.list', field: 'members', idField: 'id' }, deps)) {
    yield { rows: toSlackRows(page, 'users', teamId, 'id', undefined, deps.config.sourceId) }
  }
}

import { IngestConfigError, rawTable, type ReadContext, type SourceChunk, type RawRow } from '@chkit/plugin-ingest'

import { defaultSlackClientDeps, discoverChannels, entityId, getWorkspace, readCollectionPage, SlackCursorExpiredError, toSlackRows, type SlackClientDeps, type SlackEntity, type SlackPage } from '../client.js'
import { slackConfig } from '../config.js'
import { formatTimestamp, messageScope, timestampMicros, type SlackMessageSelection, type SlackMessageState } from '../state.js'

export const slackMessagesRaw = rawTable({ database: slackConfig.database, name: `${slackConfig.tablePrefix}_messages_raw` })

/** Temporary API cursors never enter the checkpoint; exact timestamps survive expiration. */
export async function* readMessages(
  context: ReadContext<SlackMessageSelection, SlackMessageState>,
  deps: SlackClientDeps = defaultSlackClientDeps,
): AsyncGenerator<SourceChunk<RawRow, SlackMessageState>> {
  const config = deps.config
  const teamId = await getWorkspace(context, deps)
  const scope = messageScope(teamId, config)
  if (context.state && context.state.scope !== scope) throw new IngestConfigError('Slack checkpoint belongs to a different workspace or query. Restore the configuration or use a distinct sourceId.')
  let state: SlackMessageState = context.state ?? { scope, watermark: config.historyFrom, knownChannels: [] }
  if (!state.active) {
    const channels = (await discoverChannels(context, deps)).map((channel) => entityId(channel, 'id')).sort()
    const to = context.selection.to
    const full = state.lastFullAt === undefined || timestampMicros(to) - timestampMicros(state.lastFullAt) >= BigInt(config.reconcileIntervalMs) * 1_000n
    const from = context.selection.from ?? (full ? config.historyFrom : formatTimestamp(max(timestampMicros(config.historyFrom), timestampMicros(state.watermark) - BigInt(config.overlapMs) * 1_000n)))
    if (timestampMicros(from) > timestampMicros(to)) throw new IngestConfigError('Slack selection starts after its cutoff.')
    state = { ...state, active: { kind: context.selection.backfill ? 'backfill' : full ? 'full' : 'incremental', from, to, channels, channelIndex: 0,
      latest: formatTimestamp(timestampMicros(to) + 1n), historyDone: false, threads: [],
      requestedFrom: context.selection.from, requestedTo: context.selection.requestedTo } }
    yield marker(state, 'window-open')
  } else if (context.selection.backfill && (context.selection.from !== state.active.requestedFrom || context.selection.requestedTo !== state.active.requestedTo)) {
    throw new IngestConfigError('Slack backfill bounds changed while a window is unfinished. Resume the original range or use a new backfill ID.')
  }

  while (state.active && state.active.channelIndex < state.active.channels.length) {
    context.signal.throwIfAborted()
    const work = state.active
    const channelId = work.channels[work.channelIndex]
    if (!channelId) throw new IngestConfigError('Slack checkpoint has no current channel.')
    const thread = work.threads[0]
    if (thread) {
      const after = thread.after ?? formatTimestamp(max(0n, timestampMicros(thread.root) - 1n))
      const page = await nonemptyPage(context, { channel: channelId, ts: thread.root, oldest: after,
        latest: formatTimestamp(timestampMicros(work.to) + 1n), inclusive: 'false', include_all_metadata: 'true' }, 'conversations.replies', deps)
      const replies = page.items.filter((item) => entityId(item, 'ts') !== thread.root)
      assertRange(replies, timestampMicros(after) + 1n, timestampMicros(work.to))
      const frontier = replies.length ? formatTimestamp(replies.reduce((latest, item) => max(latest, timestampMicros(entityId(item, 'ts'))), timestampMicros(after))) : undefined
      if (page.hasMore && frontier === undefined) throw new IngestConfigError('Slack thread pagination has no safe timestamp progress.')
      const threads = page.hasMore ? [{ root: thread.root, after: frontier }, ...work.threads.slice(1)] : work.threads.slice(1)
      state = { ...state, active: { ...work, threads } }
      yield page.items.length ? { rows: toSlackRows(page.items, 'messages', teamId, 'ts', channelId, config.sourceId), state } : marker(state, 'thread-complete')
      continue
    }
    if (work.historyDone) {
      state = { ...state, active: { ...work, channelIndex: work.channelIndex + 1, latest: formatTimestamp(timestampMicros(work.to) + 1n), historyDone: false } }
      yield marker(state, 'channel-complete')
      continue
    }
    const from = work.kind === 'incremental' && !state.knownChannels.includes(channelId) ? config.historyFrom : work.from
    const page = await nonemptyPage(context, { channel: channelId, oldest: formatTimestamp(max(0n, timestampMicros(from) - 1n)), latest: work.latest,
      inclusive: 'false', include_all_metadata: 'true' }, 'conversations.history', deps)
    assertRange(page.items, timestampMicros(from), timestampMicros(work.latest) - 1n)
    const latest = page.items.length ? formatTimestamp(page.items.reduce((oldest, item) => min(oldest, timestampMicros(entityId(item, 'ts'))), timestampMicros(work.latest))) : work.latest
    if (page.hasMore && (page.items.length === 0 || timestampMicros(latest) >= timestampMicros(work.latest))) throw new IngestConfigError('Slack history pagination has no safe timestamp progress.')
    const roots = config.includeReplies ? page.items.filter((item) => typeof item.reply_count === 'number' && item.reply_count > 0)
      .map((item) => typeof item.thread_ts === 'string' ? entityId(item, 'thread_ts') : entityId(item, 'ts')) : []
    state = { ...state, active: { ...work, latest, historyDone: !page.hasMore, threads: [...new Set(roots)].map((root) => ({ root })) } }
    // The page retains its bounded child queue before the history frontier advances durably.
    yield page.items.length ? { rows: toSlackRows(page.items, 'messages', teamId, 'ts', channelId, config.sourceId), state } : marker(state, 'history-complete')
  }
  if (state.active) {
    const { to, kind, channels } = state.active
    state = { scope, watermark: formatTimestamp(max(timestampMicros(state.watermark), timestampMicros(to))),
      knownChannels: [...new Set([...state.knownChannels, ...channels])].sort(), lastFullAt: kind === 'full' ? to : state.lastFullAt }
    yield marker(state, 'window-complete')
  }
}

/** Empty cursor pages use the live cursor; nonempty pages establish timestamp boundaries. */
async function nonemptyPage(
  context: ReadContext<SlackMessageSelection, SlackMessageState>, query: Record<string, string>,
  method: 'conversations.history' | 'conversations.replies', deps?: SlackClientDeps,
): Promise<SlackPage> {
  let cursor = ''
  let restarted = false
  const seen = new Set<string>()
  const parents = new Map<string, SlackEntity>()
  while (true) {
    let page: SlackPage
    try {
      page = await readCollectionPage(context, { method, field: 'messages', idField: 'ts', query, timePagination: true }, cursor, deps)
    } catch (error) {
      if (!(error instanceof SlackCursorExpiredError) || !cursor || restarted) throw error
      cursor = ''
      restarted = true
      seen.clear()
      continue
    }
    const parentOnly = method === 'conversations.replies' && page.items.every((item) => entityId(item, 'ts') === query.ts)
    if (page.items.length > 0 && (!parentOnly || !page.hasMore) || !page.hasMore) {
      for (const item of page.items) parents.set(entityId(item, 'ts'), item)
      return { ...page, items: [...parents.values()] }
    }
    for (const item of page.items) parents.set(entityId(item, 'ts'), item)
    if (!page.cursor || seen.has(page.cursor)) throw new IngestConfigError('Slack empty page did not provide a new continuation.')
    seen.add(page.cursor)
    cursor = page.cursor
  }
}

function marker(state: SlackMessageState, id: string): SourceChunk<RawRow, SlackMessageState> {
  // State-only boundaries flush previous rows without assigning identity to mutable data.
  return { rows: [], state, id }
}
function assertRange(items: SlackEntity[], from: bigint, to: bigint): void {
  if (items.some((item) => {
    const ts = timestampMicros(entityId(item, 'ts'))
    return ts < from || ts > to
  })) throw new IngestConfigError('Slack returned a message outside the requested timestamp interval.')
}
function max(left: bigint, right: bigint): bigint { return left > right ? left : right }
function min(left: bigint, right: bigint): bigint { return left < right ? left : right }

import { afterEach, describe, expect, test } from 'bun:test'

import { HttpError, definePipeline, defineStream, runIngestion, selectStreams, type FetchContext, type ReadContext, type SourceChunk } from '@chkit/plugin-ingest'
import { createMemoryDestination, createMemoryJournal } from '@chkit/plugin-ingest/testing'

import { classifySlackError, discoverChannels, readCollection, type SlackClientDeps } from '../client.js'
import { slackConfig } from '../config.js'
import * as definitions from '../index.js'
import { createSlackPipeline, slack } from '../pipeline.js'
import { readChannels } from '../sources/channels.js'
import { readUsers } from '../sources/users.js'
import { readMessages } from '../sources/messages.js'
import { messageScope, parseMessageState, slackMessageStrategy, type SlackMessageSelection, type SlackMessageState } from '../state.js'
import { channel, fixtureDeps, parentMessage, replyMessage, standaloneMessage, user } from './fixtures.js'

const readers: Record<string, (context: FetchContext, deps: SlackClientDeps) => AsyncIterable<SourceChunk>> = {
  channels: readChannels, users: readUsers,
}
const originalConfig = { ...slackConfig }
const fixtureNow = () => new Date('2023-11-15T00:00:00Z')

afterEach(() => { Object.assign(slackConfig, originalConfig) })

describe('Slack raw template', () => {
  test('exports three raw destinations and checkpointed messages without credentials', () => {
    const exported = Object.values(definitions)
    expect(exported).toContain(slack)
    expect(slack.streams).toHaveLength(3)
    expect(slack.streams.map((stream) => stream.destination.name)).toEqual(['slack_channels_raw', 'slack_users_raw', 'slack_messages_raw'])
    for (const stream of slack.streams) {
      expect(exported).toContain(stream.destination)
      expect(stream.incremental.id).toBe(stream.id.endsWith('.messages') ? 'slack.message-ranges' : 'chkit.full_sync')
    }
    expect(selectStreams([slack], ['provider:slack', 'resource:messages']).map(({ stream }) => stream.id)).toEqual(['slack.primary.messages'])
  })

  test('a pipeline binds installation identity and reader settings independently of later config edits', async () => {
    const config = { ...slackConfig, sourceId: 'slack.secondary', channels: ['C1'], conversationTypes: ['public_channel'] as const,
      includeReplies: false, pageSize: 37, messagePageSize: 12, requestIntervalMs: 7, messageIntervalMs: 11, historyFrom: '1699999999.000000' }
    const expectedScope = messageScope('T1', config)
    const requests: URL[] = [], waits: number[] = []
    const defaults = fixtureDeps()
    const deps = fixtureDeps((url, init) => { requests.push(url); return defaults.fetch(url.toString(), init) })
    deps.wait = async (milliseconds) => { waits.push(milliseconds) }
    const pipeline = createSlackPipeline(config, deps)
    config.sourceId = 'changed'
    config.channels.push('missing')
    config.historyFrom = 'invalid'
    slackConfig.sourceId = 'unrelated'
    slackConfig.includeReplies = true
    slackConfig.historyFrom = 'invalid'
    const journal = createMemoryJournal(), destination = createMemoryDestination()
    const result = await runIngestion({ selected: selectStreams([pipeline], []), backfill: undefined }, { now: fixtureNow, journal, destination })
    expect(result.ok, JSON.stringify(result)).toBe(true)
    expect(result.streams.map((stream) => stream.streamId)).toEqual(['slack.secondary.channels', 'slack.secondary.users', 'slack.secondary.messages'])
    expect(parseMessageState((await journal.readCheckpoint('slack.secondary.messages')).envelope?.state).scope).toBe(expectedScope)
    expect(destination.tables.get('default.slack_messages_raw')?.[0]?.id).toBe(JSON.stringify(['slack.secondary', 'messages', 'T1', 'C1', parentMessage.ts]))
    expect(destination.tables.get('default.slack_users_raw')?.[0]?.raw).toMatchObject({ source_id: 'slack.secondary' })
    expect(requests.filter((url) => url.pathname === '/api/conversations.list' || url.pathname === '/api/users.list').every((url) => url.searchParams.get('limit') === '37')).toBe(true)
    expect(requests.find((url) => url.pathname === '/api/conversations.history')?.searchParams.get('limit')).toBe('12')
